    public static class GuidedTutorialValidation
    {
        const BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
        static int step,seen,recoveries;static bool initialized,reduced,driving,completed,observedIgnored=true;static Exception driveError;
        static Gamepad pad;static ChartData sara;static double virtualTime;static Action<string> capture;static Action<bool,string> check;static readonly HashSet<string> shots=new HashSet<string>();
        static readonly FieldInfo active=typeof(NoteSpawner).GetField("activeNotes",Hidden),origin=typeof(AudioManager).GetField("dspSongStart",Hidden),paused=typeof(AudioManager).GetField("isPaused",Hidden);
        static readonly MethodInfo inputUpdate=typeof(InputManager).GetMethod("Update",Hidden),spawnUpdate=typeof(NoteSpawner).GetMethod("Update",Hidden);
        static double rateStart,rateWall;static string chartBeforeRate;
        public static void Restore()
        {
            EditorApplication.update-=Drive;driving=false;
            if(!initialized)return;
            TutorialGuide.Instance?.Cancel();InputManager.Instance?.UseValidationStore(null);
            if(pad!=null&&pad.added)InputSystem.RemoveDevice(pad);
            VisualPreferences.ReducedEffects=reduced;
            if(Keyboard.current!=null){InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());InputSystem.Update();}
        }
        public static bool Run(Action<bool,string> assert,Action<string> screenshot,Action<int,int> size)
        {
            check=assert;capture=screenshot;var input=InputManager.Instance;var gm=GameManager.Instance;var guide=TutorialGuide.Instance;
            if(driveError!=null)throw driveError;
            switch(step)
            {
                case 0:
                    initialized=true;reduced=VisualPreferences.ReducedEffects;VisualPreferences.ReducedEffects=false;input.UseValidationStore("RWGuidedQA_");
                    input.RemapKey(0,Key.Q);input.RemapKey(2,Key.H);input.ReloadBindings();
                    check(input.GetKeyForLane(0)==Key.Q&&input.GetKeyForLane(2)==Key.H,"Keyboard rebinding persists in an isolated validation preference namespace");
                    input.RemapKey(1,Key.Q);check(input.GetKeyForLane(0)==Key.F&&input.GetKeyForLane(1)==Key.Q,"Duplicate assignments swap lanes while preserving unique controls");input.RemapKey(0,Key.Q);
                    check(!input.RemapKey(0,Key.Escape,false)&&!input.RemapKey(0,Key.P,false),"Pause and cancel keys cannot become gameplay bindings");
                    MainMenuUI.Instance.OpenSettings();UnityEngine.Object.FindAnyObjectByType<SettingsUI>().OpenControls();size(1920,1080);step++;return false;
                case 1:
                    capture("controls-keyboard-1920.png");UnityEngine.Object.FindAnyObjectByType<ControlBindingsUI>().Listen(1,false);step++;return false;
                case 2:
                    InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(Key.Z));InputSystem.Update();typeof(ControlBindingsUI).GetMethod("Update",Hidden).Invoke(UnityEngine.Object.FindAnyObjectByType<ControlBindingsUI>(),null);
                    check(input.GetKeyForLane(1)==Key.Z,"The actual rebinding screen captures a new keyboard key");InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());InputSystem.Update();
                    pad=InputSystem.AddDevice<Gamepad>();UnityEngine.Object.FindAnyObjectByType<ControlBindingsUI>().Listen(3,true);step++;return false;
                case 3:
                    InputSystem.QueueStateEvent(pad,new GamepadState(GamepadButton.West));InputSystem.Update();typeof(ControlBindingsUI).GetMethod("Update",Hidden).Invoke(UnityEngine.Object.FindAnyObjectByType<ControlBindingsUI>(),null);inputUpdate.Invoke(input,null);
                    var controls=UnityEngine.Object.FindAnyObjectByType<ControlBindingsUI>();((UnityEngine.UI.Button[])typeof(ControlBindingsUI).GetField("pads",Hidden).GetValue(controls))[3].onClick.Invoke();
                    check(!controls.Listening,"A submit generated by the captured control cannot immediately reopen rebinding");
                    check(input.GetPadForLane(3)==GamepadButton.West&&input.UsingGamepad,"The actual settings screen captures a pad button and changes displayed input scheme");
                    inputUpdate.Invoke(input,null);check(UnityEngine.Object.FindAnyObjectByType<ControlBindingsUI>().GetComponentsInChildren<UnityEngine.UI.Button>().All(b=>b.navigation.mode==UnityEngine.UI.Navigation.Mode.Automatic),"Controller input enables navigation between the visible settings buttons");
                    InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();input.ReloadBindings();check(input.GetPadForLane(3)==GamepadButton.West,"Gamepad assignments survive a settings reload");
                    LaneController.Instance.RefreshKeyLabels();check(LaneController.Instance.GetComponentsInChildren<TextMesh>().Any(t=>t.text=="LB"),"Receptors display current controller bindings");capture("controls-gamepad-1920.png");
                    MainMenuUI.Instance.BackToMainMenu();sara=CampaignCatalog.CreateChart("Sara");sara.audioClip=ChartEditorManager.Instance.ActiveChart.audioClip;
                    check(sara.notes.Count==201&&sara.notes.Max(n=>n.endTimestamp)>150&&sara.playableEndSeconds==0,"Sara is an independently authored full-song map with no excerpt cutoff");
                    check(sara.notes.All(n=>sara.notes.Count(m=>m.timestamp<=n.timestamp&&m.endTimestamp>=n.timestamp)==1),"No tutorial moment requires chords or taps during holds");
                    MainMenuUI.Instance.OpenLevelSelect();step=39;return false;
                case 39:
                    var selector=UnityEngine.Object.FindAnyObjectByType<LevelSelectUI>(FindObjectsInactive.Include);var entries=selector.RefreshCatalog();
                    check(entries.Count(e=>string.IsNullOrEmpty(e.chartFilePath)&&e.chartData.tutorialId=="sara-basics-5")==1,"The campaign contains only one guided Sara tutorial entry");
                    entries[0].chartData=sara;entries[0].audioClip=sara.audioClip;typeof(LevelSelectUI).GetField("selectedIndex",Hidden).SetValue(selector,0);typeof(LevelSelectUI).GetMethod("Select",Hidden).Invoke(selector,new object[]{0});
                    check(((List<UnityEngine.UI.Button>)typeof(LevelSelectUI).GetField("difficultyButtons",Hidden).GetValue(selector)).Count(b=>b.gameObject.activeSelf)==0,"Custom Sara prototypes do not appear as a second campaign tutorial difficulty");
                    selector.StartSelectedLevel();check(!SocLearningFlow.Instance.IsOpen&&gm.CurrentState==GameState.Playing,"Sara enters the guided flow directly without an extra briefing screen");step=4;return false;
                case 4:
                    check(guide.IsTraining&&guide.CardOpen&&gm.CurrentState==GameState.TutorialInstruction&&Time.timeScale==0,"Campaign tutorial opens a central instruction card with song and gameplay frozen");
                    check(UnityEngine.Object.FindAnyObjectByType<InfiniteCityEnvironment>().BuildingVertexCount==0,"No rectangular building geometry remains in the background");
                    var hud=UnityEngine.Object.FindAnyObjectByType<GameplayHUD>();var meter=hud.GetComponentsInChildren<CombatPanelGraphic>().First(p=>p.name=="FirewallPlate");
                    check(meter.rectTransform.anchorMin.y>.9f&&!hud.GetComponentsInChildren<TextMeshProUGUI>().Any(t=>t.text.Contains("RYTHMWARE")||t.text.Contains("BPM")),"Gameplay shows upper-left firewall without brand or song telemetry");
                    ValidateCard();capture("tutorial-central-card-1920.png");size(1280,720);step=40;return false;
                case 40: ValidateCard();capture("tutorial-central-card-1280.png");size(1920,1080);step=41;return false;
                case 41: driving=true;EditorApplication.update+=Drive;step=5;return false;
                case 5:
                    if(!completed)return false;
                    check(seen==2047,"All eleven guided mechanics are visited, including OVERCLOCK and SOC rescue");
                    check(recoveries==7&&observedIgnored,"All three protected virus demonstrations reject hits and progress to real mitigation");
                    check(gm.CurrentScore==0&&gm.CurrentHealth==100&&!gm.TrainingSafety&&!gm.HasAchievedOverclock,"Starting the real song clears artificial practice score, safety and prefilled OVERCLOCK");
                    check(SocLearningProgress.Data.attempts.Any(a=>a.source=="tutorial-rescue"),"Practice rescue answers are recorded as tutorial learning rather than a real run rescue");
                    check(!guide.CardOpen&&!((GameObject)typeof(TutorialGuide).GetField("panel",Hidden).GetValue(guide)).activeSelf,"The full song does not launch a second overlay tutorial");capture("sara-full-song-start-1920.png");GameplayUI.IsTestPlayFromEditor=true;AudioManager.Instance.PauseSong();virtualTime=-sara.PlaybackLeadIn;step++;return false;
                case 6:
                    double until=virtualTime+8;
                    // Yield between excerpts only after an active hold is complete.
                    // Editor input updates during a paused fixture must not release its tail.
                    while(gm.CurrentState==GameState.Playing&&(virtualTime<until||((List<NoteController>)active.GetValue(NoteSpawner.Instance)).Any(n=>n!=null&&n.IsHolding)))
                    {
                        virtualTime=Math.Round(virtualTime+.02,3);Frame(virtualTime);
                        if(virtualTime>=40&&shots.Add("song"))capture("sara-complete-playing-1920.png");
                    }
                    AudioManager.Instance.PauseSong();if(gm.CurrentState!=GameState.Playing)Release();
                    check(gm.MissHits==0,"Full Sara through "+virtualTime.ToString("0.0")+"s: "+gm.CurrentState+", "+gm.PerfectHits+" Perfect, "+gm.GoodHits+" Good, "+gm.MissHits+" Miss");
                    if(gm.CurrentState==GameState.Playing&&virtualTime<160)return false;
                    check(gm.CurrentState==GameState.Victory&&gm.PerfectHits==209&&gm.GoodHits==0,"The complete authored song reaches victory with 201 heads and eight hold tails");
                    check(virtualTime>154&&virtualTime<156,"Sara finishes at the natural end of its original full audio");
                    AudioManager.Instance.StopSong();GameplayUI.IsTestPlayFromEditor=false;guide.Request(sara);ChartManager.Instance.SelectChart(sara);NoteSpawner.Instance.LoadChart(sara);AudioManager.Instance.PlaySong(sara.audioClip,sara.PlaybackLeadIn);gm.StartGame();step++;return false;
                case 7:
                    check(guide.IsTraining&&guide.CardOpen,"Reopening Sara starts a fresh guided practice");
                    InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(Key.Escape));InputSystem.Update();typeof(TutorialGuide).GetMethod("Update",Hidden).Invoke(guide,null);
                    check(gm.CurrentState==GameState.MainMenu&&!guide.IsTraining&&!gm.TrainingSafety&&!SocLearningFlow.Instance.IsOpen,"ESC exits protected practice and clears safety without opening a run debrief");
                    MainMenuUI.Instance.OpenEditor();step++;return false;
                case 8:
                    var editor=ChartEditorManager.Instance;editor.OpenCatalogChart(sara);editor.Seek(35);chartBeforeRate=editor.ActiveChart.ToJson();
                    var rateButton=UnityEngine.Object.FindAnyObjectByType<ChartEditorUI>().GetComponentsInChildren<UnityEngine.UI.Button>().First(b=>b.name=="AUDIO 1,00×");rateButton.onClick.Invoke();rateButton.onClick.Invoke();
                    check(Math.Abs(editor.PlaybackRate-.5)<.001,"The editor audio button selects half speed");editor.Play();rateStart=editor.PlaybackTime;rateWall=EditorApplication.timeSinceStartup;step++;return false;
                case 9:
                    var ed=ChartEditorManager.Instance;double measured=(ed.PlaybackTime-rateStart)/(EditorApplication.timeSinceStartup-rateWall);
                    check(measured>.40&&measured<.60,"Editor audio actually advances at half speed on the original song timeline: "+measured.ToString("0.000"));
                    ed.Pause();check(ed.ActiveChart.ToJson()==chartBeforeRate,"Slowing preview never rewrites chart timestamps or audio metadata");
                    var wave=UnityEngine.Object.FindAnyObjectByType<WaveformRenderer>();check(wave.HasSamples&&wave.AttackCount>50,"Editor detects and highlights strong audio attacks from Sara PCM");
                    capture("editor-half-speed-attacks-1920.png");check(ed.TestPlay(true),"Editor can start gameplay after a slowed preview");
                    check(Math.Abs(((AudioSource)typeof(AudioManager).GetField("musicSource",Hidden).GetValue(AudioManager.Instance)).pitch-1)<.001&&!guide.IsTraining,"Editor test gameplay uses normal audio speed and does not launch the campaign tutorial");
                    UnityEngine.Object.FindAnyObjectByType<GameplayUI>().ReturnToEditor();step++;return false;
                case 10:
                    check(Math.Abs(ChartEditorManager.Instance.PlaybackRate-.5)<.001,"Returning from gameplay retains the editor-only preview speed");ChartEditorManager.Instance.SetPlaybackRate(1);AudioManager.Instance.StopSong();gm.SetState(GameState.MainMenu);Restore();return true;
            }
            return false;
        }
        static void ValidateCard()
        {
            var guide=TutorialGuide.Instance;Canvas.ForceUpdateCanvases();
            foreach(var field in new[]{"heading","body","stepText","footer"})
            {
                var label=(TextMeshProUGUI)typeof(TutorialGuide).GetField(field,Hidden).GetValue(guide);label.ForceMeshUpdate();
                check(label.alignment==TextAlignmentOptions.Center&&label.rectTransform.anchorMin.x>=.11f&&label.rectTransform.anchorMax.x<=.89f&&!label.isTextOverflowing,"Centered tutorial "+field+" fits inside the angled frame at lesson "+guide.CurrentLesson);
            }
        }
        public static bool SongOnly(Action<bool,string> assert,Action<string> screenshot,Action<int,int> size)
        {
            if(!initialized)
            {
                initialized=true;reduced=VisualPreferences.ReducedEffects;InputManager.Instance.UseValidationStore("RWGuidedQA_");pad=InputSystem.AddDevice<Gamepad>();
                sara=CampaignCatalog.CreateChart("Sara");sara.audioClip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Music/Levels/Sara.mp3");
                GameplayUI.IsTestPlayFromEditor=true;ChartManager.Instance.SelectChart(sara);NoteSpawner.Instance.LoadChart(sara);AudioManager.Instance.PlaySong(sara.audioClip,sara.PlaybackLeadIn);GameManager.Instance.StartGame();AudioManager.Instance.PauseSong();virtualTime=-sara.PlaybackLeadIn;step=6;
            }
            return Run(assert,screenshot,size);
        }
        static void Drive()
        {
            try
            {
                if(!driving)return;var guide=TutorialGuide.Instance;var gm=GameManager.Instance;
                if(!guide.IsTraining){EditorApplication.update-=Drive;driving=false;completed=true;return;}
                if(gm.CurrentState==GameState.RescueQuestion){if(shots.Add("rescue"))capture("tutorial-rescue-question-1920.png");gm.AnswerRescue(gm.RescueQuestion.correctIndex);return;}
                if(gm.CurrentState==GameState.Reviving){if(shots.Add("countdown"))capture("tutorial-rescue-countdown-1920.png");return;}
                if(guide.CardOpen)
                {
                    float age=(float)typeof(TutorialGuide).GetField("age",Hidden).GetValue(guide);if(age<.4f)return;
                    if((seen&(1<<guide.CurrentLesson))==0){seen|=1<<guide.CurrentLesson;ValidateCard();capture("tutorial-lesson-"+guide.CurrentLesson+"-1920.png");}
                    if(guide.Recovery&&shots.Add("recovery"+guide.CurrentLesson)){recoveries|=1<<(guide.CurrentLesson-5);capture("tutorial-mitigate-"+guide.CurrentLesson+"-1920.png");}
                    guide.Continue();return;
                }
                if(gm.CurrentState==GameState.Playing)SendControls(AudioManager.Instance.SongTime,guide.CurrentLesson==1,true);
            }
            catch(Exception ex){driveError=ex;EditorApplication.update-=Drive;}
        }
        static void Frame(double t)
        {
            var am=AudioManager.Instance;paused.SetValue(am,false);origin.SetValue(am,AudioSettings.dspTime-(t-GameSettings.AudioOffsetSec));spawnUpdate.Invoke(NoteSpawner.Instance,null);SendControls(t,false,false);
            foreach(var n in ((List<NoteController>)active.GetValue(NoteSpawner.Instance)).ToArray())if(n!=null&&(n.IsHit||n.IsMissed))n.gameObject.SetActive(false);
        }
        static void SendControls(double t,bool gamepad,bool attemptObserve)
        {
            var lanes=new HashSet<int>();
            foreach(var note in ((List<NoteController>)active.GetValue(NoteSpawner.Instance)).ToArray())
            {
                if(note==null||note.IsHit||note.IsMissed)continue;
                if(note.IsHolding&&t<=note.Data.endTimestamp+.035||!note.IsHolding&&t>=note.TargetTimestamp-.035&&t<note.TargetTimestamp+.08)
                {if(!note.Data.trainingObserve||attemptObserve)lanes.Add(note.LaneIndex);}
                if(note.Data.trainingObserve&&t>note.TargetTimestamp&&t<note.TargetTimestamp+.1)observedIgnored&=!note.IsHit;
            }
            var input=InputManager.Instance;
            InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(gamepad?Array.Empty<Key>():lanes.Select(input.GetKeyForLane).ToArray()));
            var state=new GamepadState();if(gamepad)foreach(var b in lanes.Select(input.GetPadForLane)){if(b==GamepadButton.LeftTrigger)state.leftTrigger=1;else if(b==GamepadButton.RightTrigger)state.rightTrigger=1;else state=state.WithButton(b);}InputSystem.QueueStateEvent(pad,state);
            InputSystem.Update();inputUpdate.Invoke(input,null);
        }
        static void Release(){InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();}
    }
